<template>
  <section class="tenant-directory">
    <header class="directory-heading">
      <div><h2>{{ $t('tenantDirectory.title') }}</h2><p>{{ $t('tenantDirectory.subtitle') }}</p></div>
      <button type="button" class="primary-btn" @click="openCreate">＋ {{ $t('tenantDirectory.add') }}</button>
    </header>

    <div class="directory-metrics">
      <article><span>{{ $t('tenantDirectory.all') }}</span><strong>{{ summary.totalCount }}</strong></article>
      <article><span>{{ $t('tenantDirectory.active') }}</span><strong class="good">{{ summary.activeCount }}</strong></article>
      <article><span>{{ $t('tenantDirectory.inactive') }}</span><strong>{{ summary.inactiveCount }}</strong></article>
      <article><span>{{ $t('tenantDirectory.withLease') }}</span><strong class="accent">{{ summary.activeLeaseTenantCount }}</strong></article>
    </div>

    <div class="directory-filter">
      <label><span>⌕</span><input v-model.trim="keyword" :placeholder="$t('tenantDirectory.search')" @keyup.enter="search"></label>
      <select v-model="status" @change="search"><option value="">{{ $t('tenantDirectory.allStatus') }}</option><option value="active">{{ $t('tenantDirectory.active') }}</option><option value="inactive">{{ $t('tenantDirectory.inactive') }}</option></select>
      <button type="button" class="ghost-btn" @click="search">{{ $t('ui.search') }}</button>
    </div>

    <div class="directory-card">
      <div v-if="loading" class="directory-empty">{{ $t('ui.loading') }}</div>
      <div v-else-if="error" class="directory-empty error">{{ error }} <button type="button" @click="load">{{ $t('ui.retry') }}</button></div>
      <template v-else>
        <div class="directory-table-wrap"><table>
          <thead><tr><th>{{ $t('tenantDirectory.tenant') }}</th><th>{{ $t('tenantDirectory.identity') }}</th><th>{{ $t('tenantDirectory.contact') }}</th><th>{{ $t('tenantDirectory.currentLease') }}</th><th>{{ $t('tenantDirectory.depositBalance') }}</th><th>{{ $t('tenantDirectory.history') }}</th><th>{{ $t('tenantDirectory.status') }}</th><th>{{ $t('tenantDirectory.actions') }}</th></tr></thead>
          <tbody>
            <tr v-for="row in rows" :key="row.tenantId" :class="{ selected: selected?.tenantId === row.tenantId }" @click="selected = row">
              <td><strong>{{ row.fullName }}</strong><small>{{ row.email || '—' }}</small></td>
              <td>{{ row.identityNo || '—' }}</td>
              <td><span>{{ row.phone || '—' }}</span><small>{{ row.email || '' }}</small></td>
              <td><template v-if="row.currentLeaseNo"><strong>{{ row.currentLeaseNo }}</strong><small>{{ row.projectName }} · {{ row.unitNo }}</small></template><span v-else class="muted">{{ $t('tenantDirectory.noLease') }}</span></td>
              <td class="deposit-cell"><template v-if="row.currentLeaseNo"><strong>RM {{ money(row.currentDepositBalance) }}</strong><small :class="`deposit-status ${row.currentDepositStatus || 'unrecorded'}`">{{ depositCollectionStatusLabel(row.currentDepositStatus) }}</small></template><span v-else class="muted">—</span></td>
              <td>{{ $t('tenantDirectory.records', { count: row.leaseCount }) }}</td>
              <td><span class="status-pill" :class="row.status">{{ row.status === 'active' ? $t('tenantDirectory.active') : $t('tenantDirectory.inactive') }}</span></td>
              <td><div class="row-actions"><button type="button" class="detail-action" @click.stop="openDetails(row)">{{ $t('tenantDirectory.details') }}</button><button type="button" @click.stop="openEdit(row)">{{ $t('tenantDirectory.edit') }}</button><button type="button" class="status-action" @click.stop="toggleStatus(row)">{{ row.status === 'active' ? $t('tenantDirectory.disable') : $t('tenantDirectory.enable') }}</button><button type="button" class="danger" @click.stop="remove(row)">{{ $t('tenantDirectory.delete') }}</button></div></td>
            </tr>
            <tr v-if="!rows.length"><td colspan="8" class="directory-empty">{{ $t('tenantDirectory.noRows') }}</td></tr>
          </tbody>
        </table></div>
        <footer class="directory-pager"><span>{{ $t('tenantDirectory.records', { count: pager.totalRows }) }}</span><div><button type="button" :disabled="pager.page <= 1" @click="go(pager.page - 1)">‹</button><span>{{ pager.page }} / {{ pager.totalPages }}</span><button type="button" :disabled="pager.page >= pager.totalPages" @click="go(pager.page + 1)">›</button></div></footer>
      </template>
    </div>

    <div v-if="dialogOpen" class="tenant-dialog-backdrop" @click.self="closeDialog"><form class="tenant-dialog" @submit.prevent="save">
      <header><div><h3>{{ editing ? $t('tenantDirectory.editTitle') : $t('tenantDirectory.createTitle') }}</h3><p>{{ $t('tenantDirectory.subtitle') }}</p></div><button type="button" class="close" @click="closeDialog">×</button></header>
      <div class="tenant-form"><label><span>{{ $t('tenantDirectory.fullName') }} *</span><input v-model.trim="form.fullName" required maxlength="160"></label><label><span>{{ $t('tenantDirectory.identity') }}</span><input v-model.trim="form.identityNo" maxlength="120"></label><label><span>{{ $t('tenantDirectory.phone') }}</span><input v-model.trim="form.phone" maxlength="40"></label><label><span>{{ $t('tenantDirectory.email') }}</span><input v-model.trim="form.email" type="email" maxlength="190"></label><label><span>{{ $t('tenantDirectory.status') }}</span><select v-model="form.status"><option value="active">{{ $t('tenantDirectory.active') }}</option><option value="inactive">{{ $t('tenantDirectory.inactive') }}</option></select></label></div>
      <footer><button type="button" class="ghost-btn" @click="closeDialog">{{ $t('tenantDirectory.cancel') }}</button><button type="submit" class="primary-btn" :disabled="saving">{{ saving ? (editing ? $t('tenantDirectory.saving') : $t('tenantDirectory.creating')) : $t('tenantDirectory.save') }}</button></footer>
    </form></div>

    <div v-if="detailOpen" class="tenant-dialog-backdrop" @click.self="closeDetails"><section class="tenant-dialog tenant-detail-dialog">
      <header><div><h3>{{ $t('tenantDirectory.detailTitle') }}</h3><p>{{ detailRow?.fullName }} · {{ detailRow?.identityNo || '—' }}</p></div><button type="button" class="close" @click="closeDetails">×</button></header>
      <div class="tenant-detail-body">
        <div class="tenant-overview-grid"><article class="attention"><span>{{ $t('tenantDirectory.unpaidRent') }}</span><strong>RM {{ money(detailOverview.unpaidRent) }}</strong></article><article :class="{ attention: detailOverview.pendingMaintenanceCount }"><span>{{ $t('tenantDirectory.pendingMaintenance') }}</span><strong>{{ detailOverview.pendingMaintenanceCount }}</strong></article><article :class="{ attention: detailOverview.pendingSignatureCount }"><span>{{ $t('tenantDirectory.pendingSignature') }}</span><strong>{{ detailOverview.pendingSignatureCount }}</strong></article><article class="deposit-balance"><span>{{ $t('tenantDirectory.depositBalance') }}</span><strong>RM {{ money(detailOverview.depositBalance) }}</strong></article></div>
        <h4>{{ $t('tenantDirectory.leaseDetails') }}</h4>
        <p v-if="detailLoading" class="detail-empty">{{ $t('ui.loading') }}</p>
        <p v-else-if="!leaseHistory.length" class="detail-empty">{{ $t('tenantDirectory.noLeaseHistory') }}</p>
        <div v-else class="tenant-lease-list"><article v-for="lease in leaseHistory" :key="lease.leaseId"><div class="lease-head"><strong>{{ lease.leaseNo }}</strong><span class="status-pill" :class="lease.status === 'active' ? 'active' : 'inactive'">{{ leaseStatusLabel(lease.status) }}</span></div><p>{{ lease.projectName }} · {{ lease.unitNo }}</p><div class="lease-workflow"><span class="workflow-label">{{ $t('tenantDirectory.workflow') }}</span><strong>{{ workflowLabel(lease.workflowStep) }}</strong><small>{{ signatureLabel(lease.signatureStatus) }}</small></div><dl><div><dt>{{ $t('tenantDirectory.leasePeriod') }}</dt><dd>{{ lease.startDate }} ~ {{ lease.endDate }}</dd></div><div><dt>{{ $t('tenantDirectory.rent') }}</dt><dd>RM {{ money(lease.monthlyRent) }}</dd></div><div><dt>{{ $t('tenantDirectory.unpaidRent') }}</dt><dd :class="{ overdue: lease.unpaidRent > 0 }">RM {{ money(lease.unpaidRent) }}</dd></div><div><dt>{{ $t('tenantDirectory.pendingMaintenance') }}</dt><dd :class="{ overdue: lease.pendingMaintenanceCount > 0 }">{{ lease.pendingMaintenanceCount }}</dd></div></dl><div class="lease-card-actions"><button type="button" class="lease-workbench-btn" @click="openLeaseWorkbench(lease)">{{ $t('tenantDirectory.openLeaseWorkbench') }}</button></div></article></div>
      </div>
      <footer><button type="button" class="ghost-btn" @click="closeDetails">{{ $t('tenantDirectory.cancel') }}</button></footer>
    </section></div>

  </section>
</template>

<script>
import { navigate } from '../router';
import { createAdminTenant, deleteAdminTenant, fetchAdminTenantDetail, fetchAdminTenantDirectory, updateAdminTenant } from '../services/propertyApi';
const blank = () => ({ fullName: '', identityNo: '', phone: '', email: '', status: 'active' });
export default {
  inject: ['page'],
  data() { return { rows: [], summary: { totalCount: 0, activeCount: 0, inactiveCount: 0, activeLeaseTenantCount: 0 }, pager: { page: 1, pageSize: 5, totalRows: 0, totalPages: 1 }, keyword: '', status: '', loading: false, error: '', selected: null, dialogOpen: false, editing: null, form: blank(), saving: false, detailOpen: false, detailRow: null, detailLoading: false, detailOverview: { unpaidRent: 0, pendingMaintenanceCount: 0, pendingSignatureCount: 0, depositBalance: 0 }, leaseHistory: [] }; },
  mounted() { this.load(); },
  methods: {
    async load(page = this.pager.page) { this.loading = true; this.error = ''; try { const data = await fetchAdminTenantDirectory({ page, pageSize: this.pager.pageSize, keyword: this.keyword, status: this.status }); this.rows = data.rows || []; this.summary = data.summary || this.summary; this.pager = data.page || this.pager; this.selected = this.rows.find((item) => item.tenantId === this.selected?.tenantId) || this.rows[0] || null; } catch (error) { this.error = error?.message || this.$t('tenantDirectory.loadFailed'); } finally { this.loading = false; } },
    search() { this.load(1); }, go(page) { this.load(page); },
    async openDetails(row) { this.detailOpen = true; this.detailRow = row; this.leaseHistory = []; this.detailOverview = { unpaidRent: 0, pendingMaintenanceCount: 0, pendingSignatureCount: 0, depositBalance: 0 }; this.detailLoading = true; try { const data = await fetchAdminTenantDetail(row.tenantId); this.leaseHistory = data.leases || []; this.detailOverview = data.overview || this.detailOverview; } catch (error) { this.page?.showToast?.(error?.message || this.$t('tenantDirectory.loadFailed'), 'error'); } finally { this.detailLoading = false; } },
    closeDetails() { this.detailOpen = false; this.detailRow = null; this.leaseHistory = []; },
    openCreate() { this.editing = null; this.form = blank(); this.dialogOpen = true; }, openEdit(row) { this.editing = row; this.form = { fullName: row.fullName || '', identityNo: row.identityNo || '', phone: row.phone || '', email: row.email || '', status: row.status || 'active' }; this.dialogOpen = true; }, closeDialog() { if (!this.saving) this.dialogOpen = false; },
    async save() { this.saving = true; try { if (this.editing) await updateAdminTenant(this.editing.tenantId, this.form); else await createAdminTenant(this.form); this.dialogOpen = false; this.page?.showToast?.(this.$t('tenantDirectory.saved')); await this.load(this.editing ? this.pager.page : 1); } catch (error) { this.page?.showToast?.(error?.message || this.$t('tenantDirectory.loadFailed'), 'error'); } finally { this.saving = false; } },
    async toggleStatus(row) { try { await updateAdminTenant(row.tenantId, { fullName: row.fullName, identityNo: row.identityNo || '', phone: row.phone || '', email: row.email || '', status: row.status === 'active' ? 'inactive' : 'active' }); await this.load(); } catch (error) { this.page?.showToast?.(error?.message || this.$t('tenantDirectory.loadFailed'), 'error'); } },
    async remove(row) { if (row.leaseCount > 0) { this.page?.showToast?.(this.$t('tenantDirectory.deleteBlocked'), 'error'); return; } if (!window.confirm(this.$t('tenantDirectory.deleteConfirm', { name: row.fullName }))) return; try { await deleteAdminTenant(row.tenantId); this.page?.showToast?.(this.$t('tenantDirectory.deleted')); await this.load(this.rows.length === 1 && this.pager.page > 1 ? this.pager.page - 1 : this.pager.page); } catch (error) { this.page?.showToast?.(error?.message || this.$t('tenantDirectory.deleteFailed'), 'error'); } },
    money(value) { return Number(value || 0).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); },
    workflowLabel(value) { return this.$t(`tenantDirectory.workflow_${value || 'contract_pending'}`); },
    leaseStatusLabel(value) { return this.$t(`tenantDirectory.leaseStatus_${value || 'active'}`); },
    openLeaseWorkbench(lease) { if (!lease?.unitId || !lease?.leaseId) return; navigate(`/admin/properties/${encodeURIComponent(lease.unitId)}?tab=rentalManagement&rentalTab=lease&leaseId=${encodeURIComponent(lease.leaseId)}`); },
    signatureLabel(value) { return this.$t(`tenantDirectory.signature_${value || 'not_generated'}`); },
    depositCollectionStatusLabel(value) { return this.$t(`tenantDirectory.deposit_${value || 'unrecorded'}`); },
  }
};
</script>

<style scoped>
.tenant-directory{padding:18px 26px 28px}.directory-heading,.directory-filter,.directory-pager,.tenant-dialog header,.tenant-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:14px}.directory-heading h2{margin:0;color:#073c78;font-size:22px}.directory-heading p{margin:5px 0 0;color:#6d86a5;font-size:13px}.directory-metrics{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:14px;margin:18px 0}.directory-metrics article,.directory-card{background:#fff;border:1px solid #dce7f2;border-radius:12px}.directory-metrics article{padding:15px 18px;border-top:3px solid #0aa1a8}.directory-metrics span{display:block;color:#637c9a;font-size:13px}.directory-metrics strong{display:block;margin-top:5px;color:#063b75;font-size:25px}.directory-metrics .good{color:#169b5b}.directory-metrics .accent{color:#d98b00}.directory-filter{justify-content:flex-start;margin-bottom:14px}.directory-filter label{display:flex;align-items:center;gap:9px;width:min(520px,100%);padding:0 12px;background:#fff;border:1px solid #d4e0ee;border-radius:8px}.directory-filter input,.directory-filter select,.tenant-form input,.tenant-form select{width:100%;box-sizing:border-box;border:1px solid #cbdcec;border-radius:7px;background:#fff;color:#103e70;font:inherit}.directory-filter input{border:0;padding:12px 0;outline:0}.directory-filter select{width:210px;padding:11px}.directory-table-wrap{overflow:auto}.directory-card table{width:100%;min-width:1280px;border-collapse:collapse;font-size:13px}.directory-card th{padding:12px;text-align:left;color:#526d8d;background:#f5f9fc;border-bottom:1px solid #dce7f2;white-space:nowrap}.directory-card th:last-child,.directory-card td:last-child{width:250px;min-width:250px}.directory-card td{padding:11px 12px;color:#123e70;border-bottom:1px solid #e4edf5;vertical-align:middle}.directory-card tr{cursor:pointer}.directory-card tr:hover,.directory-card tr.selected{background:#fff8e8}.directory-card strong,.directory-card small{display:block}.directory-card small,.muted{margin-top:3px;color:#7890aa;font-size:12px}.deposit-cell{white-space:nowrap}.deposit-cell strong{color:#0b7f78;font-weight:800}.status-pill{display:inline-block;padding:4px 9px;border-radius:999px;font-size:12px}.status-pill.active{background:#e9f9ef;color:#168a51}.status-pill.inactive{background:#f1f4f7;color:#687b8d}.row-actions{display:flex;align-items:center;gap:6px;min-width:226px;white-space:nowrap;background:transparent;border:0!important;box-shadow:none!important}.row-actions button,.directory-pager button{margin:0;padding:5px 8px;border:1px solid #c7d9eb;border-radius:6px;color:#0d4c86;background:#fff;cursor:pointer;flex:0 0 auto}.row-actions .detail-action{background:#0b8f96;border-color:#0b8f96;color:#fff;font-weight:700}.row-actions .status-action{border-color:#e8c46b;color:#a26b00;background:#fffaf0}.row-actions .danger{color:#d64949;border-color:#f2c8c8}.directory-empty{padding:42px;text-align:center;color:#7790ac}.directory-empty.error{color:#c94646}.directory-empty button{margin-left:8px}.directory-pager{padding:12px 14px;color:#647d9c;font-size:13px}.tenant-dialog-backdrop{position:fixed;inset:0;z-index:30;display:grid;place-items:center;background:rgba(7,30,51,.42)}.tenant-dialog{width:min(620px,calc(100vw - 32px));background:#fff;border-radius:13px;box-shadow:0 20px 60px rgba(8,37,66,.25);overflow:hidden}.tenant-dialog header{padding:18px 22px;border-bottom:1px solid #e0e9f2}.tenant-dialog h3{margin:0;color:#073c78}.tenant-dialog p{margin:4px 0 0;color:#7890aa;font-size:13px}.close{border:1px solid #cbdcec;background:#fff;color:#164b7d;border-radius:7px;font-size:24px;line-height:1;padding:4px 9px}.tenant-form{display:grid;grid-template-columns:1fr 1fr;gap:15px;padding:22px}.tenant-form label{display:grid;gap:7px;color:#315979;font-size:13px}.tenant-form input,.tenant-form select{padding:10px}.tenant-dialog footer{padding:15px 22px;border-top:1px solid #e0e9f2;justify-content:flex-end}.tenant-detail-body{padding:20px 22px;max-height:65vh;overflow:auto}.tenant-overview-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.tenant-overview-grid article{display:grid;gap:6px;padding:13px;border:1px solid #dce7f2;border-radius:9px;background:#f8fbfd}.tenant-overview-grid span,.tenant-lease-list dt,.workflow-label{color:#71889f;font-size:11px}.tenant-overview-grid strong{color:#173f70;font-size:21px}.tenant-overview-grid article.attention{border-color:#efd5a1;background:#fff9ea}.tenant-overview-grid article.attention strong{color:#bd7200}.tenant-detail-body h4{margin:22px 0 10px;color:#163f70}.tenant-lease-list{display:grid;gap:10px}.tenant-lease-list article{padding:13px;border:1px solid #dce7f2;border-radius:9px;background:#fbfdff}.lease-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.lease-head strong{color:#0c477f}.tenant-lease-list p{margin:5px 0 12px;color:#72879c;font-size:12px}.lease-workflow{display:grid;grid-template-columns:auto 1fr;gap:4px 9px;align-items:center;margin:0 0 12px;padding:9px 10px;border-left:3px solid #0b8f96;border-radius:5px;background:#eef8f8}.lease-workflow strong{color:#176568;font-size:13px}.lease-workflow small{grid-column:2;color:#6d8496;font-size:11px}.tenant-lease-list dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:0}.tenant-lease-list dl div{display:grid;gap:3px}.tenant-lease-list dd{margin:0;color:#254b72;font-size:12px}.tenant-lease-list dd.overdue{color:#d24a42;font-weight:800}.detail-empty{padding:20px 0;color:#7890aa;text-align:center}@media(max-width:800px){.tenant-directory{padding:14px}.directory-metrics{grid-template-columns:1fr 1fr}.directory-heading{align-items:flex-start}.directory-filter{flex-wrap:wrap}.tenant-form,.tenant-overview-grid,.tenant-lease-list dl{grid-template-columns:1fr}}
.lease-workbench-btn{margin-top:12px;padding:7px 11px;border:1px solid #0b8f96;border-radius:6px;background:#fff;color:#087782;font-size:12px;font-weight:700;cursor:pointer}.lease-workbench-btn:hover{background:#eefafa}
.tenant-overview-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.tenant-overview-grid article.deposit-balance{border-color:#9fded7;background:#f0fbf9}.tenant-overview-grid article.deposit-balance strong{color:#087b73}.lease-card-actions{display:flex;align-items:center;justify-content:space-between;gap:9px}.lease-card-actions .lease-workbench-btn{flex:1}@media(max-width:800px){.tenant-overview-grid{grid-template-columns:1fr}}
.deposit-status.pending{color:#b97900}.deposit-status.confirmed,.deposit-status.posted{color:#168a51}.deposit-status.rejected{color:#d64949}
</style>
